mapper.insert:
INSERT INTO eg_tail_difference_adjustment_detail ( org_id, business_code, contract_code, client_code, account_code, account_name, account_balance, receivable_rent, receivable_residual_value, payable_device, payable_other, contract_status, overdue_days, rental_income_after_total, rental_income_after_lease_total, business_date, create_time, lease_date_end, tax_rate, receive_sum ) SELECT b.org_id, b.business_code, b.contract_code, COALESCE(c.client_code, MAX(b.client_code)), #{param.accountCode}, #{param.accountName}, SUM(COALESCE(b.${param.fundTypeBalance}, 0)), SUM(COALESCE(b.lease_principal_receivable_balance, 0) + COALESCE(b.lease_interest_receivable_balance, 0) + COALESCE(b.lease_interest_vat_receivable_balance, 0)), SUM(COALESCE(b.residual_value_receivable_balance, 0) + COALESCE(b.residual_value_vat_receivable_balance, 0)), SUM(COALESCE(b.supplier_payable_balance, 0)), SUM(COALESCE(b.unidentified_receipts_balance, 0)), c.contract_status, l.overdue_days, CASE WHEN '博远' = c.special_flag THEN l.rental_income_after_total END, CASE WHEN COALESCE(c.special_flag, '') != '博远' THEN l.rental_income_after_total END, CAST(#{param.businessDate} AS DATETIME), CURRENT_TIMESTAMP, c.lease_date_end, c.tax_rate, SUM(COALESCE(b.lease_principal_receivable_balance, 0) + COALESCE(b.lease_interest_receivable_balance, 0) + COALESCE(b.lease_interest_vat_receivable_balance, 0) + COALESCE(b.residual_value_receivable_balance, 0) + COALESCE(b.residual_value_vat_receivable_balance, 0)) FROM eg_contract_balance_latest b LEFT JOIN ( SELECT ec.* FROM eg_contract ec JOIN ( SELECT contract_code, org_id, MAX(id) id FROM eg_contract WHERE del_flag = '0' GROUP BY contract_code, org_id ) latest ON latest.id = ec.id ) c ON c.contract_code = b.contract_code AND c.org_id = b.org_id LEFT JOIN ( SELECT contract_code, org_id, MAX(overdue_days) overdue_days, MAX(rental_income_after_total) rental_income_after_total FROM eg_lease_income_details WHERE del_flag = '0' AND DATE_FORMAT(business_date, '%Y-%m') = DATE_FORMAT(#{param.businessDate}, '%Y-%m') GROUP BY contract_code, org_id ) l ON l.contract_code = b.contract_code AND l.org_id = b.org_id WHERE b.del_flag = '0' AND b.business_code = #{param.businessCode}
AND b.org_id IN
#{orgId}
GROUP BY b.org_id, b.business_code, b.contract_code, c.client_code, c.contract_status, c.special_flag, c.lease_date_end, c.tax_rate, l.overdue_days, l.rental_income_after_total HAVING SUM(COALESCE(b.${param.fundTypeBalance}, 0)) != 0 AND SUM(COALESCE(b.${param.fundTypeBalance}, 0)) >= COALESCE(#{param.minAccountBalance}, -1) AND SUM(COALESCE(b.${param.fundTypeBalance}, 0)) <= COALESCE(#{param.maxAccountBalance}, 1)

mapper.select:
select t.contract_code, t.org_id, t.account_code, t.account_name, t.business_date, t.account_date, t.account_balance, t.voucher_ids, t.receivable_rent, t.receivable_residual_value, t.payable_device, t.payable_other, t.contract_status, t.rental_income_after_total, t.rental_income_after_lease_total, t.overdue_days, t.client_code, t.business_code, t.lease_date_end, t.receive_sum, eoc.org_name as orgIdName, CASE WHEN tt.tax_rate is not null THEN tt.tax_rate WHEN tt.tax_rate is null and c.lease_type = '直租' THEN 0.13 WHEN tt.tax_rate is null and c.lease_type = '回租' THEN 0.06 END AS tax_rate from eg_tail_difference_adjustment_detail t inner join eg_tail_difference_adjustment t1 on t.tail_difference_adjustment_id = t1.id left join eg_org_company eoc on t.org_id = eoc.org_id and eoc.del_flag = '0' inner join eg_contract_month c on t.contract_code = c.contract_code AND c.org_id = t.org_id AND c.del_flag = '0' left join (select distinct tax.business_code,a.account_code,tax.lease_type,tax.tax_rate from eg_tax_rate tax,eg_account a where tax.fund_type = a.fund_type and tax.enable_flag = '1' and tax.del_flag = '0') tt on t.business_code = tt.business_code and t.account_code = tt.account_code and c.lease_type = tt.lease_type where 1 = 1 and t.del_flag = '0' and t1.del_flag = '0'
and t1.id in
#{item}

select * from ( select t1.contract_code, t1.org_id, t1.account_code, t1.account_name, t1.business_date, t1.account_date, t1.contract_status, t1.lease_date_end, t1.tax_rate, group_concat(voucher_ids separator ',') AS voucher_ids, sum(coalesce(t1.account_balance, 0)) as account_balance, sum(coalesce(t1.receivable_rent, 0)) as receivable_rent, sum(coalesce(t1.receivable_residual_value, 0)) as receivable_residual_value, sum(coalesce(t1.payable_device, 0)) as payable_device, sum(coalesce(t1.payable_other, 0)) as payable_other, sum(coalesce(t1.rental_income_after_total, 0)) as rental_income_after_total, sum(coalesce(t1.rental_income_after_lease_total, 0)) as rental_income_after_lease_total, sum(coalesce(t1.receive_sum, 0)) as receive_sum from eg_tail_difference_adjustment t inner join eg_tail_difference_adjustment_detail t1 on t.id = t1.tail_difference_adjustment_id where 1 = 1 and t.del_flag = '0' and t1.del_flag = '0' and t1.account_balance != 0 and t.id = #{param.tailDifferenceAdjustmentId}
and t1.contract_code like concat('%', #{param.contractCode}, '%')
and t1.contract_status = #{param.contractStatus}
and t1.contract_status in
#{item}
group by t1.contract_code, t1.org_id, t1.account_code, t1.account_name, t1.business_date, t1.account_date, t1.lease_date_end, t1.tax_rate, t1.contract_status ) a where 1=1 and a.account_balance!=0
